import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"Deploy your SaaS backend","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/single-machine-production","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/single-machine-production.md","filePath":"en/tutorials/single-machine-production.md"}'),n={name:"en/tutorials/single-machine-production.md"};function r(o,e,d,l,p,h){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="deploy-your-saas-backend" tabindex="-1">Deploy your SaaS backend <a class="header-anchor" href="#deploy-your-saas-backend" aria-label="Permalink to &quot;Deploy your SaaS backend&quot;">​</a></h1><p>Commit business modules, migrations and Worker Handlers in one source revision, then release them with the production stack. The current model serves one Organization per deployment. Internal resources still require authorization, and multiple business modules are not separate tenants. A shared deployment for several organizations requires a new data ownership design; see the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/adr/0001-single-organization-deployment.md" target="_blank" rel="noreferrer">single-organization ADR</a>.</p><p>This guide requires Docker Compose, the Rust/Node/pnpm toolchain, a reachable TLS domain and business code verified through HTTP. Run commands from the repository root. They create or update persistent production database and object volumes.</p><h2 id="configure-and-build" tabindex="-1">Configure and build <a class="header-anchor" href="#configure-and-build" aria-label="Permalink to &quot;Configure and build&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/production/env.production.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$EDITOR .env.production</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-build</span></span></code></pre></div><p>Set <code>DOMAIN</code>, <code>POSTGRES_PASSWORD</code>, <code>S3_ACCESS_KEY</code> and <code>S3_SECRET_KEY</code> in the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/deploy/production/env.production.example" target="_blank" rel="noreferrer">environment template</a>. Both <code>APP_ORIGIN</code> and <code>S3_PUBLIC_ENDPOINT</code> must point to the public HTTPS entrance. Generate deployment secrets yourself; keep the environment file outside Git and the image. Types, defaults and validation are in the <a href="./../reference/config">configuration reference</a>.</p><p>When enabling mail, API and Worker must share <code>MAIL_ENCRYPTION_KEY</code> (32-byte hex). Without SMTP configuration, mail is disabled. The telemetry endpoint may be empty. An unavailable configured mail or telemetry destination does not block ordinary business requests.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/deploy/production/Dockerfile" target="_blank" rel="noreferrer">Dockerfile</a> builds API/Worker with embedded migrations; Caddy serves the Web build. Include your migration under <code>migrations/</code> in the build context and register your Handler at the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/apps/worker/src/main.rs" target="_blank" rel="noreferrer">Worker assembly point</a>. Containers run as a non-root user with a read-only root filesystem and a temporary directory.</p><h2 id="migrate-explicitly-then-start-processes" tabindex="-1">Migrate explicitly, then start processes <a class="header-anchor" href="#migrate-explicitly-then-start-processes" aria-label="Permalink to &quot;Migrate explicitly, then start processes&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-up</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span></code></pre></div><p>The environment file is a positional <code>just</code> argument; its default is <code>.env.production</code>. The recipe runs:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PostgreSQL / Redis / RustFS healthy</span></span>
<span class="line"><span>  → one-shot migrate container</span></span>
<span class="line"><span>  → one-shot storage-init container</span></span>
<span class="line"><span>  → API / Worker / Caddy healthy</span></span></code></pre></div><p>Migration and bucket initialization run explicitly in the <code>ops</code> profile. Starting API or Worker does not change the schema. Readiness fails if migrations are absent or the applied set/checksums differ from source. A failed migration stops the recipe before application startup. Fix the cause and rerun:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-up</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span></code></pre></div><p>Only Caddy publishes 80/443 in the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/compose.production.yaml" target="_blank" rel="noreferrer">production composition</a>. API, Worker, PostgreSQL, Redis and RustFS stay on the internal network. For manual Compose commands, <code>--env-file</code> supplies interpolation and the service <code>env_file</code> also needs <code>ENV_FILE</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ENV_FILE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.env.production</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose.production.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre></div><h2 id="verify-your-public-contract" tabindex="-1">Verify your public contract <a class="header-anchor" href="#verify-your-public-contract" aria-label="Permalink to &quot;Verify your public contract&quot;">​</a></h2><p>Set shell variable <code>DOMAIN</code> to the domain from the environment file, then check:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOMAIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/health/live&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOMAIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/health/ready&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOMAIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/&quot;</span></span></code></pre></div><p>Expect 200 from both health endpoints and an HTTPS redirect from the plaintext entrance. Use your API to create, read and update a resource; verify data and Sessions survive a restart, and run a Worker task through its terminal state. Check denied access and version conflicts through the same HTTPS entrance. Health endpoints cannot prove business authorization.</p><p>Object URLs are signed against the public entrance. The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/deploy/production/Caddyfile" target="_blank" rel="noreferrer">Caddyfile</a> forwards bucket paths unchanged to RustFS; a proxy must not rewrite the signed Host or path. New business code uses this channel through Files.</p><h2 id="failures-and-process-lifecycle" tabindex="-1">Failures and process lifecycle <a class="header-anchor" href="#failures-and-process-lifecycle" aria-label="Permalink to &quot;Failures and process lifecycle&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Failure</th><th>Contract to preserve</th></tr></thead><tbody><tr><td>PostgreSQL unavailable</td><td>Readiness and database-dependent operations return controlled 503 errors with request_id; recovery needs no restart</td></tr><tr><td>Redis unavailable</td><td>Cache falls back to PostgreSQL and rate limiting uses bounded conservative fallback; readiness remains independent</td></tr><tr><td>RustFS unavailable</td><td>Database content remains readable; uploads/completion fail predictably and can be retried after recovery</td></tr><tr><td>Mail or telemetry unavailable</td><td>Business continues; Jobs retry mail and telemetry export/shutdown flush have deadlines</td></tr><tr><td>Worker stopped</td><td>Requests can enqueue; PostgreSQL preserves tasks for later claims</td></tr></tbody></table><p>API shutdown drains HTTP requests. Worker shutdown stops new claims and drains current work.</p><table tabindex="0"><thead><tr><th>Process</th><th>Internal shutdown deadlines</th><th>Compose grace period</th></tr></thead><tbody><tr><td>API</td><td>3 seconds for HTTP drain, 1 second for pool closure, then bounded telemetry flush</td><td>30 seconds</td></tr><tr><td>Worker</td><td>Active work uses <code>JOB_SHUTDOWN_SECS</code> (default 10 seconds), health HTTP/pool get 1 second each, then bounded telemetry flush</td><td>45 seconds</td></tr></tbody></table><p>Trace shutdown gets at most 2 seconds; the metrics reader uses its SDK&#39;s 5-second shutdown wait. Production smoke and backup require API exit before 25 seconds and Worker before 40 seconds, with drain logs, below forced-kill grace periods. Increasing active-work deadlines also requires checking total budgets and Compose grace periods. Your Handler must honor cancellation, leases and exit deadlines so maintenance cannot wait indefinitely.</p><h2 id="upgrade-and-recover" tabindex="-1">Upgrade and recover <a class="header-anchor" href="#upgrade-and-recover" aria-label="Permalink to &quot;Upgrade and recover&quot;">​</a></h2><p>Create and verify an archive using the <a href="./backup-restore">backup guide</a>, stop the old application, build the reviewed revision and migrate:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-down</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-up</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span></code></pre></div><p><code>production-down</code> preserves volumes. If migration fails, keep the database and failure logs, fix the cause and retry. A new migration may already have committed; switching to an old image does not roll back the schema. Restore into an independent environment with the application revision corresponding to the archive.</p><p>Reproducible framework checks are:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/production-compose.test.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-smoke</span></span></code></pre></div><p><code>production-smoke</code> creates test secrets and a temporary production stack. It verifies the reference application, dependency failures, persistence and draining through real TLS, then removes its test volumes. It requires free ports 80/443 and cannot share an existing production entrance. Add a separate HTTPS journey for your own business.</p><p>Next: <a href="./backup-restore">Protect business data and verify independent recovery</a>.</p><hr><p>Source version：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/tutorials/21-single-machine-production.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,36)])])}const k=a(n,[["render",r]]);export{u as __pageData,k as default};
